export const DEFAULT_PALETTE = "classic";
export const PALETTE_STORAGE_KEY = "hagit_palette";

export function getPalette(id: string | null | undefined): Palette {
    return PALETTES.find((p) => p.id === id) ?? PALETTES[0];
}

export const isPaletteId = (id: unknown): id is string => typeof id === "string" && PALETTES.some((p) => p.id === id);

function surfaceVars(s: Surfaces) {
    return `--paper:${s.paper};--paper-alt:${s.paperAlt};--ink:${s.ink};--ink-muted:${s.inkMuted};--border:${s.border};--card-bg:${s.card};`;
}

function brandVars(p: Palette) {
    return Object.entries(p.brand).map(([k, v]) => `--brand-${k}:${v};`).join("");
}

/** CSS for every palette × mode, injected once in the root layout. */
export function paletteCss(): string {
    const classic = PALETTES[0];
    const rules = [
        // `--ink-fixed` stays dark in both modes (used for hard shadows and "ink" fills).
        `:root{${brandVars(classic)}${surfaceVars(BASE_LIGHT)}--brand:${classic.brand[600]};--ink-fixed:${BASE_LIGHT.ink};}`,
        `.dark{${surfaceVars(BASE_DARK)}--brand:${classic.brand[400]};}`,
    ];
    for (const p of PALETTES.slice(1)) {
        const light = p.light ?? BASE_LIGHT;
        rules.push(`[data-palette="${p.id}"]{${brandVars(p)}--brand:${p.brand[600]};${p.light ? `${surfaceVars(light)}--ink-fixed:${light.ink};` : ""}}`);
        rules.push(`.dark[data-palette="${p.id}"]{--brand:${p.brand[400]};${p.dark ? surfaceVars(p.dark) : ""}}`);
    }
    return rules.join("\n");
}

/** Runs before first paint so the stored palette never flashes the default. */
export const paletteBootScript = `try{var p=localStorage.getItem("${PALETTE_STORAGE_KEY}");if(p)document.documentElement.setAttribute("data-palette",p)}catch(e){}`;
